// PROFILES generated by tools/roster2profiles.py from people/*.json (active team) and students.csv (idle background). Do not edit by hand.
const PROFILES=[{"code": "S02", "team": "MIT Media Lab", "interests": ["informal learning", "wearables", "working memory", "cognitive load", "learning by teaching"], "skills": ["simulation", "wearable sensing", "local models", "physiological signals", "agent evaluation"], "project": "an AI student on smart glasses that asks naive questions about what the wearer sees, timed by a simulated working memory", "alt": ["documentation site, a hand-written agent loop and three project ideas", "Telegram scheduler agent that pushes back", "AI student on Mentra Live glasses", "working memory simulation on Aria Gen 2", "evaluating the AI student", "on-phone agent that keeps the glasses usable"], "bio": "Builds context-aware wearable agents for informal learning. Instead of predicting what someone wants to learn, the agents create learning opportunities: an AI student on smart glasses asks naive questions, so answering exercises recall. Grounds the designs in Baddeley's working memory model and cognitive load theory, and mostly runs small local models.", "site": "https://mitmedialab.github.io/agents2026-hyung/", "name": "Hyungwoon Lee", "active": true, "builds": [{"week": "W01", "title": "documentation site, a hand-written agent loop and three project ideas", "summary": "Built the course documentation site with Claude Code: a three.js 'Saturn' sphere whose ring is the menu, a cursor heatmap and brush, and a markdown system with nested panels. Wrote a minimal agent loop by hand on Qwen2.5-3B: the Sheep Summator Supervisor watches a sheep-counting machine that gets tired or hungry and miscounts, and can scold, shake or feed it until the count succeeds. Proposed three final project ideas: the Random Questioner (a context-aware debater that asks Socratic questions about objects around you), the Agentic Rebel (a wearable that questions your decisions at the right moment to surface hidden assumptions) and the Intention Detector (telling whether a learner cares about the process or only the result, and fostering learning only where they care)."}, {"week": "W02", "title": "Telegram scheduler agent that pushes back", "summary": "A personal scheduler, still in daily use, behind an owner-only Telegram bot (smolagents ToolCallingAgent with Claude). Two deterministic tools: resolve_when turns phrases like 'Fri EOD' into exact times or lists the candidates, and schedule_store reads, validates and conflict-checks a markdown schedule. A skill defines the format and when to push back on over-commitment with evidence; Google Calendar (read-only) and Google Maps (travel time only) come in over MCP. It deliberately keeps the human in the loop, on the theory that taking part in scheduling helps you remember and keep to it."}, {"week": "W03", "title": "AI student on Mentra Live glasses", "summary": "Set the cognitive augmentation objective: create informal learning opportunities with context-aware wearables, encourage motivation and curiosity, and exercise information retrieval through cognitive tension. Built a curious-student agent: a photo from the glasses goes through object detection (RT-DETR), a scene description (SmolVLM) and Qwen2.5-1.5B, which picks one object (half the time an unfamiliar one, half the time one connected to what it knows) and asks one naive question aloud. Spoken answers are transcribed, scored for voice emotion and answered as a student that records what it learned. Everything runs locally; the human-agent interaction space, failure modes and an evaluation plan (a quiz before and after) are written up. Also proposed that the course agent become a sparring partner that quizzes students instead of a middleman."}, {"week": "W04", "title": "working memory simulation on Aria Gen 2", "summary": "Analysed AiGet and Promemassist as agent environments, then simulated the wearer's working memory from Aria Gen 2 streams. A visual cache holds four detected objects that blur and fade unless looked at again; a phonological loop holds seven content words from the wearer's or others' speech; a central executive estimates cognitive load from heart-rate variability (an XGBoost model trained on the CLAS dataset, AUC 0.79 on unseen people, fine-tuned on the wearer's own ratings) and from gaze; an episodic buffer keeps four task episodes. The AI student turns what was seen and heard into notes ranked by the wearer's preferences, asks only at low-load moments, and stores what it learns in its own long-term memory."}, {"week": "W05", "title": "evaluating the AI student", "summary": "Defined six scores for the AI student: timing of the moment, grounding in what the wearer perceived, question quality, reading the answer correctly, precision of what it stores, and planting mistakes at a chosen level of Bloom's taxonomy (a new setting lets the student be wrong on purpose so that the wearer corrects it). Ran 90 trials over 10 simulated scenes with Claude Haiku 5.5 as judge, comparing Haiku with Qwen3-VL-4B and Gemma 3 4B on a laptop CPU: Haiku passed 40% of trials on the first try against 13%, and the local models failed mostly at storing knowledge, copying the skill file's example or believing vague answers. Also moved the agent out of the memory model, so the simulation is an environment of its own."}, {"week": "W06", "title": "on-phone agent that keeps the glasses usable", "summary": "An Android (Kotlin) agent running Qwen2.5-1.5B through llama.cpp under a GBNF grammar, so every output is a well-formed tool call. It watches the Mentra glasses and the phone over Bluetooth and read-only ADB, retakes photos that are too dark or blurry, and caps photo size, rate and streaming as the glasses heat up; as the phone heats up it steps itself down from a vision model to a text model to rules only. Deterministic safety limits back the model, and an MCP server exposes the same 18 tools to external agents. In tasks verified from device state, Claude Opus 5.5 and the 1.5B model passed everything and the 0.5B looped, but the 1.5B sometimes claimed a success it hadn't achieved."}], "notes": [{"term": "informal learning", "description": "Learning in daily life rather than in the classroom. Instead of predicting what someone wants to learn from their past patterns, which can hold back growth, the agent opens new learning opportunities from the objects and moments around them. Treats motivation and curiosity as the bottleneck: 'process-as-goal' learning has no grade at the end, so it depends on the person wanting to explore. The aim is personal growth, not coursework."}, {"term": "wearables", "description": "Smart glasses and on-body sensors (camera, microphones, gaze, heart rate) that give an agent context on both the environment and the wearer. Has built on Mentra Live and Aria Gen 2 glasses, prefers small models that run locally for privacy, and is interested in how hardware limits such as heat and battery shape what an agent can do."}, {"term": "working memory", "description": "Baddeley's working memory model (visuospatial sketchpad, phonological loop, central executive, episodic buffer) as an environment an agent can observe: what the wearer has just seen and heard, how it fades, and what they are doing now. Builds on Promemassist and AiGet, adding gaze and physiological signals to model the central executive."}, {"term": "cognitive load", "description": "Estimating intrinsic, extraneous and germane load from heart-rate variability and eye movements, both as a research question and as the signal for when an agent may interrupt. Wary of the limited ecological validity of in-lab datasets such as CLAS, so models are fine-tuned on the wearer's own ratings."}, {"term": "learning by teaching", "description": "Flipping the usual roles: instead of asking the AI, the AI asks you. A naive AI student, sometimes wrong on purpose at a chosen level of Bloom's taxonomy, makes the wearer explain and correct it. This creates cognitive tension (in the spirit of antagonistic AI) and exercises information retrieval, which daily life rarely demands while the internet floods us with things to encode."}], "avatar": {"t": 0, "h": 0, "s": 1, "p": 0, "hs": 0, "g": 1}}, {"code": "S07", "team": "MIT Media Lab", "interests": ["memory systems", "sleep", "metacognition", "sub-agent models of the mind", "creativity"], "skills": ["agent evaluation", "physiological signals", "sound design", "simulation", "3D"], "project": "re:dream, an agent that interviews you about last night's dream and lets you step back into it as a spatial soundscape", "alt": ["Downloads-folder naming agent on a local model", "Calendar++: goal agents that debate your week", "Frontier Map: calibrating judgment of AI capability", "Liminal: an environment for guiding a sleeper to the edge of sleep", "Evaluating Liminal", "A Pocket 4 that remembers where things were left"], "bio": "Roma Luo studies at Harvard's Graduate School of Design and is cross-registered at the MIT Media Lab for Cognitive Agents (MAS.S60). He builds agents that act on real things, from his own sleep data to a camera on his desk, and cares about memory and about how well people judge what AI can do.", "site": "https://mitmedialab.github.io/agents2026-roma/", "name": "Roma Luo", "active": true, "builds": [{"week": "W01", "title": "Downloads-folder naming agent on a local model", "summary": "He wrote an agent loop by hand, with no framework, around a local GGUF model (llama-cpp-python) that renames files in a real Windows Downloads folder according to a naming convention it reads first. Renames are dry-run by default, verified by looking again, and can be undone. He treated it as an experiment in moving the tutorial's observe, act, observe loop onto a real filesystem to see how it fails."}, {"week": "W02", "title": "Calendar++: goal agents that debate your week", "summary": "He designed and built a native macOS calendar in Swift where each of the user's life goals is held by its own agent. In a weekly meeting the agents propose and rebut, a clerk tallies, and the user signs before anything is scheduled: the model proposes, code decides. It reads the calendar through EventKit and includes its own MCP client; he notes openly that it does not use the smolagents interface the rubric asked for."}, {"week": "W03", "title": "Frontier Map: calibrating judgment of AI capability", "summary": "A calm desktop agent that trains one skill: predicting how well Claude will do a task. Before each delegation a small dial asks for a one-click prediction; an observer agent watches the conversation, counts corrections and resolves the outcome; a radial map shows where expectations are accurate, too high or too low. Predictions cannot be skipped, because 'this is obviously fine' is the belief being tested."}, {"week": "W04", "title": "Liminal: an environment for guiding a sleeper to the edge of sleep", "summary": "He replayed one real morning of his consumer EEG headband data on a 3D turntable built in Blender: the record is the night, its rings the sleep stages and brain waves. The tone arm drops and music plays only when the agent steps in, shaping tempo, volume and brightness to guide the sleeper into light sleep and wake them to catch an idea. The data pipeline, model and site were built; the agent was still a rule policy."}, {"week": "W05", "title": "Evaluating Liminal", "summary": "He compared silence, a rule agent and an LLM agent (Claude Haiku 4.5) on 8 tasks, 5 trials each, 120 episodes traced in Langfuse. The rule agent won overall (pass@1 0.68); the LLM was the best at keeping a sleeper asleep (15 of 15 guard tasks) but succeeded in only 8 of 25 dives, where it must guide the sleeper into light sleep and wake them with an idea. pass@5 looked perfect while pass^5 was 0 on every dive task. The most telling failure: the agent asked a still-sleeping person for their idea in 7 of 25 LLM dives, and an 'act, then check' layer removed it."}, {"week": "W06", "title": "A Pocket 4 that remembers where things were left", "summary": "He turned a DJI Osmo Pocket 4 into an embodied agent exposed as an MCP server: it can look around, point, zoom and take photos within guard rails, and every few seconds a vision model lists what is in view and stores it in SQLite. Asked where an AirPods case was, it found it 3 of 3 times in view, 2 of 3 beside the desk out of view, and 0 of 3 when it had been taken away by hand; misses came from the vision model naming the case differently on different days. The camera also ignored the Bluetooth commands the community had documented."}], "notes": [{"term": "memory systems", "description": "How an agent, or a person with an agent, keeps and retrieves what matters. His course site is his own memory of the course, answering questions from a vault of markdown files. His week 6 camera remembers where each object was last seen, and its failures came from memory: the vision model named the same AirPods case differently on different days. His final project keeps a dream memory across nights that surfaces recurring places, people and motifs."}, {"term": "sleep", "description": "The edge of sleep as a place where ideas appear. His week 4 and 5 work replays one real morning of his consumer EEG headband and asks an agent to shape sound so a sleeper reaches light sleep (N1), then wakes them before deeper sleep to catch an idea. His final project moves to the morning after: recalling and re-entering a dream."}, {"term": "metacognition", "description": "Judging what AI can and cannot do. Once execution is delegated, he argues, the skill that matters is calibrated reliance. His week 3 Frontier Map asks for a one-click prediction before every delegation to Claude, resolves the outcome by watching the conversation, and maps where expectations of AI are too high or too low."}, {"term": "sub-agent models of the mind", "description": "Treating one person's goals or voices as several agents. His week 2 Calendar++ gives each life goal to its own agent; the agents debate in a weekly meeting, code tallies the result and nothing reaches the calendar until the user signs. The aim is to make invisible disagreements visible and leave the decision to the person."}, {"term": "creativity", "description": "Supporting the moment an idea forms rather than generating ideas for people. Liminal tries to catch ideas at sleep onset; re:dream treats a dream as material the dreamer can revisit, with an agent that asks questions instead of interpreting."}], "avatar": {"t": 5, "h": 4, "s": 0, "p": 1, "hs": 1, "g": 0}}, {"code": "S08", "team": "City Science", "interests": ["cities", "social interaction", "ambient agents"], "skills": ["3D", "simulation", "urban design"], "project": "City Agents: simulate whether a city space will attract social interaction", "alt": ["Build an Agent", "Connect to MCP servers", "New interfaces for agents", "KoKoRo: desktop tasks measured by accuracy, interruptions, time and mental effort", "City Agents: an interactive environment in Blender"], "bio": "Media designer and architect: digital media experiences, collaborative co-construction and the machine's role in city making; tools for healthier cities.", "site": "https://mitmedialab.github.io/agents2026-leticia/", "name": "Leticia", "active": true, "builds": [{"week": "W01", "title": "Build an Agent", "summary": ""}, {"week": "W02", "title": "Connect to MCP servers", "summary": ""}, {"week": "W03", "title": "New interfaces for agents", "summary": ""}, {"week": "W04", "title": "KoKoRo: desktop tasks measured by accuracy, interruptions, time and mental effort", "summary": ""}, {"week": "W05", "title": "City Agents: an interactive environment in Blender", "summary": ""}], "notes": [], "avatar": {"t": 2, "h": 2, "s": 2, "p": 3, "hs": 3, "g": 0}}, {"code": "S17", "team": "MIT Center for Constructive Communication", "interests": ["sensemaking", "reflective listening", "human interpretive authority", "qualitative analysis without coding"], "skills": ["interfaces", "interaction specification", "physical prototyping"], "project": "reflective listening tools that help people make sense of first-hand stories through spoken, evidence-linked reflection", "alt": ["Agent Eden course website", "Astrology reading agent", "Reflective listening prototype (Notes in Margin Memos)"], "bio": "Maya Detwiller is a listener in the MIT Media Lab course Cognitive Agents (2026). They design agents for deep listening and sensemaking, where the AI does the mechanical labor and the human keeps the interpretive judgment.", "site": "https://mitmedialab.github.io/agents2026-maya/", "name": "Maya Detwiller", "active": true, "builds": [{"week": "W01", "title": "Agent Eden course website", "summary": "They set up their course website, themed as a Garden of Eden (\"a place to name creations, eat an apple, or talk to a snake\"), with a table of weekly assignments that open project pages in a modal. A GitHub Actions workflow publishes the website folder to GitHub Pages. The week 1 write-up pages are still placeholders."}, {"week": "W02", "title": "Astrology reading agent", "summary": "They built a smolagents CodeAgent on a Claude model with tools for geocoding a birthplace, computing a natal chart, and reading and writing Google Docs. The agent writes a chart reading into a Google Doc, then checks the doc for unresolved comments and replies to each with an alternate-placement suggestion. A reusable skill file sets the reading's voice: warm, second-person, plain-language trait first and astrological reasoning in parentheses."}, {"week": "W03", "title": "Reflective listening prototype (Notes in Margin Memos)", "summary": "They specified and built a transcript reader (FastAPI backend, React frontend) where the listener highlights passages, leaves margin memos, and records a spoken reflection at the end of each transcript, transcribed locally with faster-whisper. An AI review step proposes connections to the listener's research questions with cited evidence, which they approve, edit, or reject before it is filed into a running memo per question. A second phase added AI gists for every conversation in the corpus and next-step suggestions of unvisited conversations grounded in what the listener wants to hear next; the build log notes these were verified with real model calls and synthetic audio, with the author as the only tester so far."}], "notes": [{"term": "sensemaking", "description": "Making sense of many people's first-hand stories in response to the same open-ended question. They see the traditional process of highlighting, codestorming, and tagging as frictionful and cognitively taxing, and as a place where contextual and relational information gets lost. Their work explores how agents can hold multiple threads so the listener can orient and reorient their curiosity instead."}, {"term": "reflective listening", "description": "Treating listening and reflection as the main task rather than categorizing. Their week 3 prototype asks the listener to speak a voice reflection at the end of each transcript, anchored by their own research questions, and files approved reflections with their evidence into a running memo."}, {"term": "human interpretive authority", "description": "Keeping the human as the interpretive engine when AI joins an analysis. Their designs hide the AI's interpretation until the user has voiced their own, keep AI-proposed items visibly distinct, require explicit approval before anything enters the memo, and archive edits and rejections for an interpretive record."}, {"term": "qualitative analysis without coding", "description": "Moving away from top-down codebooks and hard-to-iterate tags toward a more fluid process anchored on the listener's goals. They draw on research on LLM-supported thematic analysis without coding and on reflexivity-centered analysis tools, and their phase 2 spec proposes AI-synthesized \"code families\" as a stepping stone toward a codebook rather than a tagging system."}], "avatar": {"t": 4, "h": 3, "s": 0, "p": 4, "hs": 1, "g": 0}}, {"code": "S01", "team": "MIT Media Lab", "interests": ["mental health", "rumination", "meta-awareness"], "skills": ["agent loops", "evaluation", "web"], "project": "lemmespiralforyou: an agent that learns how you spiral and guides healthy de-spiral steps while watching distress", "alt": ["agentofchaos", "goofballtimes", "lemmespiralforyou", "spiralverse: choose worry thoughts, track feelings, review patterns before reframes", "spiralbench", "sol lamba", "lemmespiralforyou presentation"], "bio": "Project log, Fall 2026. Works on noticing repetitive thinking patterns and guiding de-spiral steps.", "site": "https://mitmedialab.github.io/agents2026-egemen/", "name": "Egemen", "active": false}, {"code": "S03", "team": "MIT Media Lab", "interests": ["language learning", "peer learning", "robots"], "skills": ["agents", "simulation", "education"], "project": "agents for learning (final project page)", "alt": ["week 01", "week 02", "week 03", "LangTable: a robot guiding three language learners to correct one another", "week 05", "week 06", "week 07"], "bio": "Building agents for learning: AI agents for cognitive augmentation.", "site": "https://mitmedialab.github.io/agents2026-jad/", "name": "Jad", "active": false}, {"code": "S04", "team": "MIT Media Lab", "interests": ["habits", "cognition", "perceptual friction"], "skills": ["tool use", "memory", "wearables"], "project": "LemmeSpiralForYou: turning unproductive repetitive thinking into concrete, distanced thinking", "alt": ["What is an AI Agent?", "Tool Use + Interfaces", "Human + Agent", "10bit: a companion that interrupts harmful phone habits without nagging", "Evaluating Agents", "Computer Use", "Memory"], "bio": "Weekly experiments in agents, cognition, tools, memory, interaction and human augmentation.", "site": "https://mitmedialab.github.io/agents2026-juan-ruben/", "name": "Juan Ruben", "active": false}, {"code": "S05", "team": "MIT Media Lab", "interests": ["aging", "memory", "attention", "pharmacy design"], "skills": ["simulation", "evaluation"], "project": "Clara: compare how the same phone call affects older people with different memory and attention", "alt": ["Clara: pharmacy call simulation for older people with different memory and attention"], "bio": "Weekly documentation site (page-flip book).", "site": "https://mitmedialab.github.io/agents2026-manasi/", "name": "Manasi", "active": false}, {"code": "S06", "team": "Fluid Interfaces", "interests": ["sleep", "computational design", "interfaces"], "skills": ["design", "evaluation", "device agents"], "project": "sleep-cue helpers tested against a recorded night (Paprika)", "alt": ["Building My First Agent", "Building Tools and Skills", "Designing Human-Agent Interfaces", "Paprika: test sleep-cue helpers against a recorded night", "Evaluating an Agent Environment", "Device Use Agent"], "bio": "Computational designer; documentation site for MAS.S60.", "site": "https://mitmedialab.github.io/agents2026-ray/", "name": "Ray", "active": false}, {"code": "S09", "team": "Harvard GSD", "interests": ["embodied AI", "tangible interaction", "ambient computing", "play"], "skills": ["interaction design", "creative technology"], "project": "Pause and Predict: stop a computer agent, explain why, choose its next action", "alt": ["Week 1", "Week 2", "Week 3", "Pause and Predict: people stop a computer agent, explain why and choose its next action", "Week 5", "Week 6"], "bio": "Interaction designer and creative technologist (MDes Mediums); technologies that support human growth, creativity and connection.", "site": "https://mitmedialab.github.io/agents2026-lilith/", "name": "Lilith", "active": false}, {"code": "S10", "team": "MIT Media Lab", "interests": ["spatial sound", "light", "listening agents"], "skills": ["3D", "audio", "web"], "project": "Ludwig: a listening agent that moves among humming machines and reports them", "alt": ["week 1", "Ludwig: a listening agent reports locations and changes of humming machines"], "bio": "An underwater world of light and spatial sound: every pod is a week.", "site": "https://mitmedialab.github.io/agents2026-mateo/", "name": "Mateo", "active": false}, {"code": "S11", "team": "MIT Media Lab", "interests": ["explanations", "maps", "ambient insights"], "skills": ["tools", "MCP", "evaluation"], "project": "an agent that explains local population facts on a map, graded with a quiz", "alt": ["An agent with tools, skills and MCP", "Ambient Insights", "Environment for explanations", "Evaluation", "A Real Device"], "bio": "Documenting work in AI Agents for Cognitive Augmentation, fall 2026.", "site": "https://mitmedialab.github.io/agents2026-matti/", "name": "Matti", "active": false}, {"code": "S12", "team": "MIT Media Lab", "interests": ["retail design", "simulated people", "navigation"], "skills": ["simulation", "design"], "project": "MarketSims: redesign a supermarket and compare six simulated shoppers", "alt": ["MarketSims: redesign a supermarket and compare how six simulated shoppers navigate it"], "bio": "MAS.S60 Fall 2026 site.", "site": "https://mitmedialab.github.io/agents2026-stacey/", "name": "Stacey", "active": false}, {"code": "S13", "team": "MIT Media Lab", "interests": ["robots", "rescue", "human oversight"], "skills": ["simulation", "robotics", "evaluation"], "project": "FireBench: test a fire-rescue robot's choices and when it asks a human commander", "alt": ["Week 1", "FireBench: a rescue robot saves people without reckless risks, a commander can step in"], "bio": "Fourteen weeks: a mirror-ball of clickable weeks.", "site": "https://mitmedialab.github.io/agents2026-yanning/", "name": "Yanning", "active": false}, {"code": "S14", "team": "MIT Media Lab", "interests": ["wearables", "design tools", "simulation"], "skills": ["simulation", "product design"], "project": "a simulation workspace for wearable designers to test leg-resistance ideas before prototyping", "alt": ["leg band simulation: sketches into pull checks, leg raise to 40 degrees"], "bio": "Connecting Dots: a weekly field journal for AI agents for cognitive augmentation.", "site": "https://mitmedialab.github.io/agents2026-yue/", "name": "Yue", "active": false}, {"code": "S15", "team": "Harvard GSD", "interests": ["computational design", "human-robot interaction", "education"], "skills": ["digital fabrication", "programming", "mentorship"], "project": "Ideation board: people and an AI take turns generating creative uses for a brick", "alt": ["Minimal agent loop", "Tool use", "Human–agent design", "Ideation board: people and an AI take turns generating creative uses for a brick", "Evaluation", "Device-use agents", "Project proposals"], "bio": "Master in Design Studies student; computational design, human-machine and human-robot interaction, digital fabrication; former educator and youth program director.", "site": "https://mitmedialab.github.io/agents2026-david/", "name": "David", "active": false}, {"code": "S16", "team": "Harvard GSD", "interests": ["design", "peer discovery", "memory"], "skills": ["interfaces", "archives", "evaluation"], "project": "Three directions for cognitive augmentation", "alt": ["Agent Loop — Difficult Conversation Rehearsal", "Design Reference Tracker — Memory Frog", "Human–Agent Interaction Interface for Design", "Our Cognitive Gardens — classmates discover related projects and contact one another", "Our Cognitive Gardens — Evaluation"], "bio": "Field archive of weekly experiments: each disc opens a build with process, saved runs, failures and reflections.", "site": "https://mitmedialab.github.io/agents2026-raine/", "name": "Raine", "active": false}, {"code": "PROF-1", "team": "staff · instructor · Fluid Interfaces", "interests": ["software agents", "human-computer interaction", "cognitive augmentation"], "skills": ["research direction", "HCI", "AI"], "project": "how agents can augment human cognitive abilities rather than replace them", "alt": [], "bio": "Professor of Media Arts and Sciences; research at the intersection of human-computer interaction and AI; co-directs Advancing Humans with AI; pioneered the concept of software agents.", "site": "https://www.media.mit.edu/people/pattie/overview/", "name": "Pattie Maes", "active": false}, {"code": "PROF-2", "team": "staff · instructor · Fluid Interfaces", "interests": ["reasoning", "critical thinking", "wearable cognition", "philosophy"], "skills": ["AI", "cognitive science", "design"], "project": "Socratic AI assistants and wearable cognitive tools for critical thinking", "alt": [], "bio": "Researcher and artist exploring how AI can amplify rather than erode human reasoning; designs Socratic AI assistants and wearable cognitive tools.", "site": "https://www.media.mit.edu/people/vdanry/overview/", "name": "Valdemar Danry", "active": false}, {"code": "TA-1", "team": "staff · TA · Fluid Interfaces", "interests": ["audio", "wearable sensing", "assistive technology"], "skills": ["signal processing", "multimodal AI", "entrepreneurship"], "project": "real-world audio intelligence and assistive wearable tools", "alt": [], "bio": "Builds evidence-based AI systems at the intersection of HCI, audio signal processing and wearable sensing.", "site": "https://www.media.mit.edu/people/", "name": "Chitralekha Gupta", "active": false}, {"code": "TA-2", "team": "staff · TA · Cyborg Psychology", "interests": ["interaction design", "human impact of technology"], "skills": ["design research", "HCI"], "project": "the shifting role of the designer in the age of AI", "alt": [], "bio": "Interaction designer and HCI researcher focused on the human impact of design and technology.", "site": "https://designsingapore.org/stories/rachel-poonsiriwong-is-finding-the-human-middle-ground-in-the-age-of-ai/", "name": "Rachel Poonsiriwong", "active": false}, {"code": "TA-3", "team": "staff · TA · Cyborg Psychology", "interests": ["human-AI interaction", "interpretability", "well-being"], "skills": ["agents", "interfaces", "research"], "project": "collaborative AI systems that complement human cognition", "alt": [], "bio": "Multidisciplinary researcher on human-AI interaction: assistants, agents and interfaces that complement human cognition, decision-making and well-being; mechanistic interpretability.", "site": "https://www.media.mit.edu/people/skarny/overview/", "name": "Sheer Karny", "active": false}, {"code": "TA-4", "team": "staff · TA · Fluid Interfaces", "interests": ["memory", "cognitive neuroscience", "wearables"], "skills": ["wearable AI", "neuroscience", "prototyping"], "project": "wearable AI that augments memory while preserving human agency", "alt": [], "bio": "PhD researcher drawing on cognitive neuroscience to shape how wearable AI can augment human memory while preserving agency.", "site": "https://www.media.mit.edu/people/wazeer/overview/", "name": "Wazeer Zulfikar", "active": false}, {"code": "TA-5", "team": "staff · TA · Fluid Interfaces", "interests": ["behavioral AI", "personalization", "proactive interaction"], "skills": ["embedded systems", "computer science", "AI"], "project": "proactive, personalized always-on wearable agents", "alt": [], "bio": "Freestyle technologist and engineer: behavioral AI, personalization and proactive interactions with always-on multimodal wearables.", "site": "https://www.media.mit.edu/people/yasith/overview/", "name": "Yasith Samaradivakara", "active": false}];
